                post_hook={
                    "sql": "DROP TABLE IF EXISTS public.custom_facebook_marketing_anveshan_customcampaigns_data; CREATE TABLE public.custom_facebook_marketing_anveshan_customcampaigns_data AS SELECT (_airbyte_data.ad_id)::varchar AS ad_id, (_airbyte_data.ad_name)::varchar AS ad_name, (_airbyte_data.adset_id)::varchar AS adset_id, (_airbyte_data.adset_name)::varchar AS adset_name, (_airbyte_data.campaign_id)::varchar AS campaign_id, (_airbyte_data.campaign_name)::varchar AS campaign_name, (_airbyte_data.account_id)::varchar AS account_id, (_airbyte_data.account_name)::varchar AS account_name, (_airbyte_data.account_currency)::varchar AS account_currency, (_airbyte_data.objective)::varchar AS objective, (_airbyte_data.optimization_goal)::varchar AS optimization_goal, (_airbyte_data.quality_ranking)::varchar AS quality_ranking, (_airbyte_data.date_start)::date AS date_start, (_airbyte_data.date_stop)::date AS date_stop, (_airbyte_data.reach)::float AS reach, (_airbyte_data.spend)::float AS spend, (_airbyte_data.clicks)::bigint AS clicks, (_airbyte_data.impressions)::bigint AS impressions, (_airbyte_data.frequency)::float AS frequency, (_airbyte_data.inline_link_clicks)::bigint AS inline_link_clicks, (_airbyte_data.inline_post_engagement)::bigint AS inline_post_engagement, _airbyte_data.actions AS actions, _airbyte_data.conversions AS conversions, _airbyte_data.action_values AS action_values, _airbyte_data.conversion_values AS conversion_values, _airbyte_data.outbound_clicks AS outbound_clicks, _airbyte_data.purchase_roas AS purchase_roas, _airbyte_data.website_purchase_roas AS website_purchase_roas FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY (_airbyte_data.ad_id)::varchar,(_airbyte_data.date_start)::date ORDER BY _airbyte_emitted_at DESC ) AS rw FROM public._airbyte_raw_Custom_Facebook_Marketing_Anveshan_Acqui_customcampaigns_data ) WHERE rw = 1; DROP TABLE IF EXISTS public.anweshan_FACEBOOK_CONSOLIDATED; CREATE TABLE public.anweshan_FACEBOOK_CONSOLIDATED AS select Adset_Name, Adset_ID, fb.ad_id, fb.ad_name, \'FACEBOOK\' as account_name, account_id, campaign_name, Campaign_ID, CAST(FB.date_start AS date) AS Date, SUM(CLICKS) AS Clicks, SUM(COALESCE(inline_link_clicks, 0)) AS Link_Clicks, SUM(SPEND) AS Spend, SUM(IMPRESSIONS) AS Impressions, SUM(COALESCE(Fc.Conversions, 0)) AS Conversions, \'FACEBOOK\' AS Channel, \'FACEBOOK\' AS Account from public.custom_facebook_marketing_anveshan_new_customcampaigns_data fb LEFT JOIN ( SELECT ad_id, ad_name, date_start, SUM(CAST(c.value::VARCHAR AS FLOAT)) AS Conversions FROM PUBLIC.custom_facebook_marketing_anveshan_new_customcampaigns_data t, t.actions AS c WHERE c.action_type::VARCHAR = \'offsite_conversion.fb_pixel_purchase\' GROUP BY ad_id, ad_name, date_start HAVING SUM(CAST(c.value::VARCHAR AS FLOAT)) IS NOT NULL ) Fc ON FB.ad_id = Fc.ad_id AND FB.date_start = Fc.date_start LEFT JOIN ( SELECT ad_id, ad_name, date_start, SUM(CAST(cv.value::VARCHAR AS FLOAT)) AS Conversion_Value FROM public.custom_facebook_marketing_anveshan_new_customcampaigns_data t, t.action_values AS cv WHERE cv.action_type::VARCHAR = \'offsite_conversion.fb_pixel_purchase\' GROUP BY ad_id, ad_name, date_start HAVING SUM(CAST(cv.value::VARCHAR AS FLOAT)) IS NOT NULL ) Fcv ON FB.ad_id = Fcv.ad_id AND FB.date_start = Fcv.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(c.value::VARCHAR AS FLOAT)) AS add_to_carts FROM public.custom_facebook_marketing_anveshan_new_customcampaigns_data t, t.actions AS c WHERE c.action_type::VARCHAR = \'offsite_conversion.fb_pixel_add_to_cart\' GROUP BY ad_id, date_start HAVING SUM(CAST(c.value::VARCHAR AS FLOAT)) IS NOT NULL ) Fd ON FB.ad_id = Fd.ad_id AND FB.date_start = Fd.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(cv.value::VARCHAR AS FLOAT)) AS add_to_cart_value FROM public.custom_facebook_marketing_anveshan_new_customcampaigns_data t, t.action_values AS cv WHERE cv.action_type::VARCHAR = \'offsite_conversion.fb_pixel_add_to_cart\' GROUP BY ad_id, date_start HAVING SUM(CAST(cv.value::VARCHAR AS FLOAT)) IS NOT NULL ) Fdv ON FB.ad_id = Fdv.ad_id AND FB.date_start = Fdv.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(c.value::VARCHAR AS FLOAT)) AS landing_page_views FROM public.custom_facebook_marketing_anveshan_new_customcampaigns_data t, t.actions AS c WHERE c.action_type::VARCHAR = \'landing_page_view\' GROUP BY ad_id, date_start HAVING SUM(CAST(c.value::VARCHAR AS FLOAT)) IS NOT NULL ) Fe ON FB.ad_id = Fe.ad_id AND FB.date_start = Fe.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(c.value::VARCHAR AS FLOAT)) AS initiate_checkouts FROM public.custom_facebook_marketing_anveshan_new_customcampaigns_data t, t.actions AS c WHERE c.action_type::VARCHAR = \'offsite_conversion.fb_pixel_initiate_checkout\' GROUP BY ad_id, date_start HAVING SUM(CAST(c.value::VARCHAR AS FLOAT)) IS NOT NULL ) Ff ON FB.ad_id = Ff.ad_id AND FB.date_start = Ff.date_start LEFT JOIN ( SELECT ad_id, date_start, SUM(CAST(cv.value::VARCHAR AS FLOAT)) AS initiate_checkouts_value FROM public.custom_facebook_marketing_anveshan_new_customcampaigns_data t, t.action_values AS cv WHERE cv.action_type::VARCHAR = \'offsite_conversion.fb_pixel_initiate_checkout\' GROUP BY ad_id, date_start HAVING SUM(CAST(cv.value::VARCHAR AS FLOAT)) IS NOT NULL ) Ffv ON FB.ad_id = Ffv.ad_id AND FB.date_start = Ffv.date_start GROUP BY Adset_Name, Adset_ID, FB.ad_id, FB.ad_name, Account_Name, Account_ID, Campaign_Name, Campaign_ID, FB.date_start;",
